__doc__ = """Compute-resource abstractions for serial and parallel lowering."""

from .checksum import stable_normalize
from .codecontainer import (
    MultiFrameExpandContainer,
    HiddenLayersContainer,
)
from .libroutinevar import ExternalImport, LibRoutineLocalVariable


class ParallelMultiFrameExpandContainer(
    HiddenLayersContainer, MultiFrameExpandContainer
):
    """Multiframe expansion container that injects required parallel imports."""

    REQUIRED_IMPORTS = []

    def __init__(
        self,
        *,
        context,
        local_variable_class=None,
        local_variable_capture=None,
        **buildargs,
    ):
        super().__init__(
            context=context,
            local_variable_class=local_variable_class,
            local_variable_capture=local_variable_capture,
            **buildargs,
        )
        for libimport in type(self).REQUIRED_IMPORTS:
            self.requires(ExternalImport(libimport))

    def generate_head_containers(self, **kwargs):
        yield from super().generate_head_containers(**kwargs)

    def generate_foot_containers(self, **kwargs):
        yield from super().generate_foot_containers(**kwargs)


class ComputeResource:
    """A compute resource to manage parallel resources and thread-safety features"""

    _count = 0
    DEFAULT_LOCAL_VARIABLE_CLASS = None

    def __init__(
        self,
        descriptor=None,
        outer_layer=None,
        next_layer=None,
        max_value=(1 << 32),
    ):
        if descriptor is None:
            descriptor = f"Resource_{type(self)._count}"
        self._descriptor = descriptor
        self._next_layer = next_layer
        self._max_value = max_value
        type(self)._count += 1
        if outer_layer is not None:
            outer_layer.append_resource_layer(self)

    @property
    def next_layer(self):
        """access read-only proporty next_layer"""
        return self._next_layer

    def checksum_payload(self):
        """Return a stable payload describing this resource tree."""
        state = {}
        for key, value in self.__dict__.items():
            if key == "_next_layer":
                continue
            state[key] = stable_normalize(value)
        return {
            "class": f"{type(self).__module__}.{type(self).__qualname__}",
            "state": state,
            "next_layer": None
            if self._next_layer is None
            else self._next_layer.checksum_payload(),
        }

    @next_layer.setter
    def next_layer(self, new_layer):
        """set the next layer after some checks"""
        if self._next_layer is None:
            self._next_layer = new_layer
            return
        raise ValueError("Layer already set")

    def append_resource_layer(self, new_layer):
        """add another resource layer inside (all the way to the end)"""
        this_layer = self
        while this_layer.next_layer is not None:
            this_layer = this_layer.next_layer
        this_layer.next_layer = new_layer

    def create_mfe_container(
        self, *, context, local_variable_capture
    ) -> None | MultiFrameExpandContainer:
        # if the resource cannot cover the whole requested range
        return MultiFrameExpandContainer(
            context=context,
            local_variable_capture=local_variable_capture,
        )

    def create_combine_container(
        self, first, second, *, context, local_variable_capture
    ) -> None | MultiFrameExpandContainer:
        return None

    def get_default_resource(self):
        """get the default resource once the initial tree is consumed"""
        return type(self)("DEFAULT", outer_layer=self)

    def peel_layer(self):
        """forward to the next layer"""
        if self.next_layer is None:
            return self.get_default_resource()
        return self.next_layer

    def exhaust(self, variable):
        """exhaust the resource"""
        return variable, self.peel_layer()

    def request_mfe_container(
        self,
        variable,
        *,
        name=None,
        local_variable_capture=None,
        loop_capture=None,
        context,
    ):
        if name is None:
            name = variable.name
        # name += "_H" + str(hash(variable))[-8:]

        if variable.max_value > self._max_value:
            first, second = variable.split(self._max_value)

            if loop_capture is None:
                return self, None

            # this will trigger the loop handling of these two first, and that might split them again.
            loop_capture.requires(second)
            loop_capture.requires(first)

            mfe_container = self.create_combine_container(
                first,
                second,
                context=context,
                local_variable_capture=local_variable_capture,
            )

        else:
            mfe_container = self.create_mfe_container(
                context=context,
                local_variable_capture=local_variable_capture,
            )

        # if the resource cannot handle it, push to outer scope
        if mfe_container is None:
            return self, None

        # prime the output variable
        mfe_container.assign_multiframe_variable(
            variable,
            name=name,
            local_variable_class=type(self).DEFAULT_LOCAL_VARIABLE_CLASS,
        )

        return self.peel_layer(), mfe_container


class EmptyComputeResource(ComputeResource):
    """empty compute resource"""

    def __init__(self):
        super().__init__("EMTPY")

    def create_mfe_container(
        self, *, context, local_variable_capture
    ) -> None | MultiFrameExpandContainer:
        return None


class DefaultComputeResource(ComputeResource):
    """the default resource if none is given - no parallelism, nothing"""

    def __init__(self):
        super().__init__("DEFAULT")
